import { Entity, Column, PrimaryGeneratedColumn } from 'typeorm';

@Entity('settings')
export class Setting {
  @PrimaryGeneratedColumn()
  id: number;

  // Identity
  @Column({ default: 'My Billiard & Cafe' })
  businessName: string;

  @Column({ type: 'text', nullable: true })
  address: string;

  @Column({ nullable: true })
  contact: string;

  @Column({ nullable: true })
  socialMediaLink: string;

  @Column({ nullable: true })
  logoPath: string;

  // Policy
  @Column({ type: 'decimal', precision: 5, scale: 2, default: 0 })
  ppnPercentage: number;

  @Column({ type: 'decimal', precision: 5, scale: 2, default: 0 })
  serviceChargePercentage: number;

  @Column({ type: 'int', default: 100 })
  roundingKelipatan: number; // e.g., 100, 500

  // Operational
  @Column({ default: '00:00' })
  businessDayOffset: string; // e.g., '02:00' for 2 AM closing

  @Column({ default: '03:00' })
  autoMaintenanceTime: string; // e.g., '03:00'

  @Column({ type: 'int', default: 15 })
  lateToleranceMinutes: number;

  @Column({ type: 'int', default: 30 })
  maintenanceAuditLogDays: number; // Hapus audit log lebih dari N hari

  @Column({ type: 'int', default: 90 })
  maintenanceSessionDays: number; // Hapus session lebih dari N hari

  @Column({ type: 'int', default: 90 })
  maintenanceTransactionDays: number; // Arsipkan transaksi lebih dari N hari

  @Column({ type: 'int', default: 365 })
  maintenanceCashflowDays: number; // Arsipkan cashflow lebih dari N hari

  // Hardware/System
  @Column({ type: 'json', nullable: true })
  availablePaymentMethods: string[]; // e.g., ['Cash', 'QRIS', 'Transfer']

  @Column({ default: '127.0.0.1' })
  mqttBrokerAddress: string;

  @Column({ type: 'text', nullable: true })
  clientQrisString: string;

  @Column({ type: 'text', nullable: true })
  qrisTemplatePath: string;

  @Column({ type: 'text', nullable: true })
  qrisMerchantName: string;

  @Column({ type: 'text', nullable: true })
  tftWallpaper: string | null;

  // Invoice Specific
  @Column({ nullable: true })
  invoiceBusinessName: string;

  @Column({ type: 'text', nullable: true })
  invoiceAddress: string;

  @Column({ nullable: true })
  invoiceContact: string;

  @Column({ nullable: true })
  invoiceSocialMedia: string;

  @Column({ type: 'text', nullable: true })
  invoiceFooterNote: string;

  // Custom Duration Pricing (Dynamic by Category)
  // Format: [ { categoryId: 1, basePrice: 60000, timeSlots: [ {start, end, price} ] } ]
  @Column({ type: 'json', nullable: true })
  customPricingDynamic: {
    categoryId: number;
    basePrice: number;
    timeSlots: { start: string; end: string; price: number }[];
  }[];

  @Column({ type: 'json', nullable: true })
  availableShifts: { name: string; startTime: string; endTime: string }[];

  @Column({ type: 'int', default: 10 })
  shiftEndingWarningMinutes: number;

  @Column({ type: 'int', default: 5 })
  endingSoonThreshold: number;

  @Column({ type: 'int', default: 2000 })
  balanceBuffer: number;

  @Column({ type: 'int', default: 15 })
  balanceWarningMinutes: number;

  @Column({ type: 'int', default: 1000 })
  royaltyPointsPerAmount: number; // e.g., 1000 means 1 point per Rp 1.000 spent

  @Column({ type: 'int', default: 200 })
  royaltyPointRedeemValue: number; // e.g., 200 means 1 point is worth Rp 200 when redeemed

  @Column({ type: 'int', default: 5 })
  scratchBombWinRate: number; // Win percentage for the scratch card game (e.g. 5 for 5%)

  @Column({ type: 'varchar', default: '1,2,5,10,20,50,100' })
  scratchBombRewards: string; // Dynamic list of game rewards, comma separated

  @Column({ type: 'int', default: 25 })
  scratchBombAvgWinPts: number; // Set average jackpot value manually

  @Column({ type: 'boolean', default: false })
  gamificationAutoPilot: boolean; // Flag to enable autonomous AI AI

  @Column({ type: 'int', default: 5000000 })
  gamificationTargetSurplus: number; // The target surplus you want for auto pilot

  @Column({ type: 'int', default: 2 })
  scratchBombPlayCost: number; // Cost in points to play the scratch card game //
  @Column({ type: 'int', default: 90 })
  pointExpiryDays: number; // Duration in days before points expire

  @Column({ type: 'int', default: 0 })
  scratchBombPool: number; // The "Treasury" or budget pool for game wins

  @Column({ type: 'int', default: 15 })
  mahjongSlotWinRate: number; // Win percentage for Mahjong slot (e.g. 15 for 15% high-win chance)

  @Column({ type: 'int', default: 0 })
  mahjongSlotPool: number; // Dedicated pool for Mahjong slot

  @Column({ type: 'boolean', default: false })
  isEmergencyMode: boolean;

  @Column({ type: 'int', default: 80 })
  printerWidth: number; // e.g., 80, 58, 75

  @Column({ type: 'json', nullable: true })
  displayPromotions: {
    title: string;
    desc: string;
    tag: string;
    color: string;
    image: string;
  }[];

  @Column({ nullable: true })
  ownerPhone: string;

  @Column({ default: false })
  autoReportEnabled: boolean;

  @Column({ default: '23:55' })
  reportSchedule: string; // HH:mm

  @Column({ type: 'text', nullable: true })
  waTemplateWelcome: string;

  @Column({ type: 'int', default: 5 })
  aiStaffingRatio: number;

  @Column({ default: false })
  aiAutoPromote: boolean;

  @Column({ type: 'decimal', precision: 3, scale: 2, default: 0.6 })
  aiAutoPromoteThreshold: number;

  @Column({ type: 'text', nullable: true })
  waTemplateSessionEnd: string;

  @Column({ default: false })
  autoSettlementEnabled: boolean;

  @Column({ default: '04:00' })
  autoSettlementTime: string; // HH:mm

  // Dynamic Approval Config
  @Column({ type: 'json', nullable: true })
  approvalConfig: {
    WASTE: number[];
    EXPENSE: number[];
    CLOSING: number[];
    STOCK_UPDATE: number[];
    STOCK_IN: number[];
    DATA_EDIT: number[];
  };

  // Dynamic Bounce-Back Promo Rules
  @Column({ type: 'json', nullable: true })
  bounceBackConfig: {
    tierName: string;
    minAmount: number;
    maxAmount: number;
    rewardType: string; // 'FREE_ITEM' | 'DISCOUNT_FIXED' | 'FREE_BILLIARD_MINUTES'
    rewardValue: number | string;
    freeMenuItemId?: number;
    minClaimTransaction: number;
    expiryDays: number;
    validStartTime?: string;
    validEndTime?: string;
  }[];

  // Global IoT Bypass
  @Column({ type: 'boolean', default: false })
  isIotBypassed: boolean;

  // Feature Toggles
  @Column({ type: 'boolean', default: false })
  enableAISalesOrchestrator: boolean;

  @Column({ type: 'boolean', default: false })
  enableBounceBack: boolean;

  // Real-time Notification Toggles
  @Column({ type: 'boolean', default: true })
  notifyTransactions: boolean;

  @Column({ type: 'boolean', default: true })
  notifyLowStock: boolean;

  @Column({ type: 'boolean', default: true })
  notifyApprovals: boolean;
  
  @Column({ type: 'boolean', default: true })
  notifyNewSession: boolean;

  @Column({ type: 'boolean', default: true })
  notifyLicenseExpiry: boolean;

  @Column({ type: 'boolean', default: true })
  notifyCancelOrder: boolean;

  @Column({ type: 'boolean', default: true })
  notifyManualLight: boolean;

  // Visual Floor Plan Layout Map (JSON array of elements)
  @Column({ type: 'json', nullable: true })
  floorPlanLayout: any;
}

